WHERE fixed_assets.is_active = 1
AND fixed_assets.type = 3

  AND fixed_assets.company_id = #{filter.companyId}


    AND fixed_assets.branch_id = #{filter.branchId}


  AND fixed_assets.location_id = #{filter.locationId}


  AND fixed_assets.vendor_id = #{filter.vendorId}


  AND (
  fixed_assets.fixed_asset_code LIKE CONCAT("%", #{filter.searchText}, "%")
  OR fixed_assets.name LIKE CONCAT("%", #{filter.searchText}, "%")
  )

mapper.select:
SELECT



ORDER BY


    ${filter.orderBy}


    fixed_assets.id DESC



  LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(1)
FROM fixed_assets
WHERE is_active = 1
AND `type` = 3
AND fixed_asset_code = #{investmentAssetCode}

  AND id != #{id}

mapper.update:
UPDATE fixed_asset_files SET
    is_active = 2,
    modified = NOW(),
    modified_by = #{userId}
    WHERE fixed_asset_id = #{inId};

UPDATE fixed_assets SET
is_active = 2, modified = NOW(), modified_by = #{userId}
WHERE id = #{id}
AND type = 3

mapper.select:
SELECT depr_account AS accountId, (SELECT CONCAT(account_codes, ' · ', account_description) FROM chart_accounts WHERE id = fixed_assets.depr_account) AS accountName, 1 AS isDepreAcc FROM fixed_assets WHERE is_active = 1 AND `type` = 3 AND is_depre = 1
AND company_id = #{filter.companyId}
AND branch_id = #{filter.branchId}
AND `date` <= #{filter.date}
GROUP BY fixed_assets.depr_account ORDER BY fixed_assets.date

SELECT accum_account AS accountId, (SELECT CONCAT(account_codes, ' · ', account_description) FROM chart_accounts WHERE id = fixed_assets.accum_account) AS accountName, 0 AS isDepreAcc FROM fixed_assets WHERE is_active = 1 AND `type` = 3 AND is_depre = 1
AND company_id = #{filter.companyId}
AND branch_id = #{filter.branchId}
AND `date` <= #{filter.date}
GROUP BY fixed_assets.accum_account ORDER BY fixed_assets.date

SELECT SUM(debit)-SUM(credit) AS amount
FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id
WHERE is_approve=1 AND is_active=1 AND is_depreciated=1 AND is_investment = 1 AND is_appreciation = 0
AND chart_account_id = #{accountId}

  AND company_id = #{filter.companyId}


      AND branch_id = #{filter.branchId}


  AND `date` <= #{filter.date}

SELECT ROUND(SUM(credit), 2)
FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id
WHERE is_approve=1 AND is_active=1 AND is_depreciated=1 AND is_investment = 1 AND is_appreciation = 0
AND chart_account_id = #{accountId}

    AND company_id <= #{filter.companyId}


    AND branch_id = #{filter.branchId}


    AND `date` <= #{filter.date}

SELECT ROUND(SUM(debit), 2)
FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id
WHERE is_approve=1 AND is_active=1 AND is_depreciated=1 AND is_investment = 1 AND is_appreciation = 0
AND chart_account_id = #{accountId}

    AND company_id <= #{filter.companyId}


    AND branch_id = #{filter.branchId}


    AND `date` <= #{filter.date}

SELECT fixed_assets.id AS id, fixed_assets.date AS date, fixed_assets.fixed_asset_code AS code, fixed_assets.name AS assetName, fixed_assets.name AS name, fixed_assets.cost AS cost, fixed_assets.asset_life AS assetLife, fixed_assets.depr_method AS deprMethod, fixed_assets.salvage_value AS salvageValue, fixed_assets.business_use_percentage AS businessUsePercentage, CASE WHEN is_depre = 0 THEN 0 ELSE DATEDIFF(#{filter.date}, fixed_assets.date) END AS depreciationDayAmount, IFNULL(CONCAT(users_fa.first_name, ' ', users_fa.last_name), '') AS createdBy, IFNULL(CONCAT(users_fm.first_name, ' ', users_fm.last_name), '') AS modifiedBy, fixed_assets.photo_name AS photoName, fixed_assets.description AS description, fixed_assets.cost_remain AS costRemain, fixed_assets.is_in_used AS isInUsed, fixed_assets.purchase_order_number AS purchaseOrderNumber, fixed_assets.serial_number AS serialNumber, fixed_assets.warranty_expires AS warrantyExpires, fixed_assets.is_depre AS isDepre, fixed_assets.created AS created, fixed_assets.modified AS modified FROM fixed_assets LEFT JOIN users AS users_fa ON users_fa.id = fixed_assets.created_by LEFT JOIN users AS users_fm ON users_fm.id = fixed_assets.modified_by WHERE fixed_assets.is_active = 1 AND fixed_assets.`type` = 3 AND fixed_assets.is_depre = 1
AND fixed_assets.company_id = #{filter.companyId}
AND fixed_assets.branch_id = #{filter.branchId}
AND fixed_assets.`date` <= #{filter.date}
AND fixed_assets.depr_account = #{accountId}
AND fixed_assets.accum_account = #{accountId}
